def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise RuntimeError(f'PATCH_ANCHOR_MISSING:{label}')
    return text.replace(old, new, 1)


c = CONTROL.read_text(encoding='utf-8')
c = replace_once(c, 'from collections import Counter\n', 'from collections import Counter, deque\n', 'deque_import')
c = replace_once(c, 'VERSION = "A4_001A_COMPLETE_CONTROL_POINT_V2.3.0"', 'VERSION = "A4_001A_COMPLETE_CONTROL_POINT_V2.4.0"', 'control_version')
