new_preflight = 'gates = {"python": sys.version_info >= (3, 12), "engine_exists": ENGINE.exists(), "poll": POLL >= 5, "coverage": 0.8 <= PER_CYCLE <= 1, "runtime_audit": 10 <= RUNTIME_AUDIT_SECONDS <= 60 and RUNTIME_MAX_REPAIRS >= 1, "mode": mode in {"selftest", "env_test", "live", "watchdog"}}'
